function cDash(){const u=S.user,m=S.exams.filter(e=>e.cand.includes(u.id)),L={Available:m.filter(e=>e.st=="Ongoing"),Upcoming:m.filter(e=>e.st=="Published"),Completed:m.filter(e=>e.st=="Completed")};
return `<div class="card hero row sp"><div><p class="sm" style="font-weight:600;opacity:.8">CANDIDATE EXAMINATION DASHBOARD</p><h1>Welcome back, ${u.name}</h1><p class="mu">Registration: ${u.reg} · Computer Science</p></div><div class="row">${Object.keys(L).map(k=>`<div class="stat" style="background:#ffffff26;border-color:#ffffff33;text-align:center;min-width:92px"><b>${L[k].length}</b><span class="sm">${k}</span></div>`).join("")}</div></div>
<div class="row sp" style="margin:28px 0 14px"><h2>Your Examinations</h2><div class="row" style="background:var(--bg);border:1px solid var(--bd);border-radius:12px;padding:4px;gap:2px">${Object.keys(L).map(k=>`<button class="tab ${S.tab==k?"on":""}" onclick="S.tab='${k}';R()">${k} (${L[k].length})</button>`).join("")}</div></div>
<div class="grid g2">${L[S.tab].map(e=>`<div class="card col"><div class="row sp"><span class="mu sm">${e.code}</span><span class="pill ${e.st=="Ongoing"?(S.at&&S.at.id==e.id?"wn":"ok"):pc(e.st)}">${e.st=="Ongoing"?(e.id=="cs301"?"In Progress":"Available"):e.st=="Published"?"Opens "+e.win.split("–")[0]:"Completed"}</span></div><h3 style="font-size:19px">${e.title}</h3><p class="mu">${e.desc}</p>
<div class="stat row sp sm"><span>⏱ ${e.dur} mins</span><span>❔ ${e.qs.length||6} questions</span><span>🏅 ${e.marks} marks</span></div><p class="mu sm">🗓 Window: ${e.win}</p>
${e.st=="Ongoing"?`<button class="btn w" onclick="go('instr','${e.id}')">${e.id=="cs301"?"Resume Examination":"View Instructions & Enter"}</button>`:e.st=="Published"?`<button class="btn g w" disabled>Not yet available — access opens at start time</button>`:`<button class="btn g w" onclick="go('results')">Open Report</button>`}</div>`).join("")||`<div class="card mu">Nothing here yet. New assignments appear when an examiner enrolls you.</div>`}</div>
<h2 style="margin:30px 0 14px">Recent Published Results</h2><div class="card row sp" style="max-width:480px"><div><span class="mu sm">DB-204-MID</span><h3>Database Internals & Indexing</h3><b>🏅 43 / 50 (86%)</b></div><div class="col" style="align-items:flex-end"><span class="pill ok">Passed</span><button class="btn g s" onclick="go('report')">Open Report</button></div></div>`}
function instr(){const e=S.exams.find(x=>x.id==S.ex);return `<div style="max-width:860px;margin:auto"><a href="#" class="mu" onclick="go('dash');return false">← Back to Examinations</a><div class="card col" style="margin-top:14px"><p class="in pill" style="align-self:flex-start">${e.code}</p><h1>${e.title}</h1><p class="mu">${e.desc}</p>
<div class="grid g4"><div class="stat"><span class="mu sm">Duration</span><b style="font-size:18px">${e.dur} Minutes</b></div><div class="stat"><span class="mu sm">Total Marks</span><b style="font-size:18px">${e.marks}</b></div><div class="stat"><span class="mu sm">Questions</span><b style="font-size:18px">${qs(e).length} Items</b></div><div class="stat"><span class="mu sm">Passing</span><b style="font-size:18px">${e.pass} Marks</b></div></div><div class="stat sm">🗓 Availability window: <b>${e.win}</b></div>
<h3>Examination Instructions</h3><ul class="mu"><li>Multiple-select questions require all correct options for full credit.</li><li>Answers are saved locally and synchronised whenever the network is available.</li><li>Use the Digital Scratchpad for rough work; notes are never submitted.</li><li>Mark questions for review and return via the Question Navigation Panel.</li></ul>
<div class="rule"><b>Rules & Integrity Guidelines</b><ul><li>The timer is server-authoritative. Network interruptions never pause or extend it.</li><li>At 00:00 your attempt is finalised with all answers accepted so far.</li><li>Leaving the window may be logged as an indicator for examiner review. It is not proof of misconduct.</li><li>Do not share content or use unauthorised assistance.</li></ul></div>
<label style="flex-direction:row;font-weight:500"><input type="checkbox" style="width:auto" id="c1" onchange="chk()">I confirm that I am ${S.user.name} (${S.user.reg}) and am taking this assessment independently.</label><label style="flex-direction:row;font-weight:500"><input type="checkbox" style="width:auto" id="c2" onchange="chk()">I agree to the instructions, server-authoritative timing and integrity rules.</label>
<button class="btn w" id="go" disabled onclick="start('${e.id}')">${e.id=="cs301"?"Resume":"Start"} Examination Workspace</button></div></div>`}
const chk=()=>$("#go").disabled=!($("#c1").checked&&$("#c2").checked);
